function calcular(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const N = 365;
  const pedidos = (datos && datos.tablas && datos.tablas.pedidos) || [];
  const esVenta = (e) => e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad";
  const conteo = {};
  for (const p of pedidos) {
    if (!p || !p.creado) continue;
    if (!esVenta(p.estado)) continue;
    const d = dia(p.creado);
    conteo[d] = (conteo[d] || 0) + 1;
  }
  const serie = [];
  let total = 0;
  for (let k = N - 1; k >= 0; k--) {
    const etiqueta = dia(new Date(Date.parse(datos.hoy) - k * 86400000).toISOString());
    const v = conteo[etiqueta] || 0;
    serie.push({ etiqueta: etiqueta, valor: v });
    total += v;
  }
  return {
    valor: total,
    unidad: "pedidos",
    serie: serie,
    nota: "Cuenta pedidos confirmados, enviados, entregados y con novedad por d\u00eda (hora Bogot\u00e1) en los \u00faltimos 365 d\u00edas, hoy incluido."
  };
}

