function consultar(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var fmt = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' '); };
  var N = 7;
  var hoyMs = Date.parse(datos.hoy);
  var limiteDia = dia(new Date(hoyMs - N * 86400000).toISOString());
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var clientes = (datos.tablas && datos.tablas.clientes) || [];
  var nomCli = {};
  for (var i = 0; i < clientes.length; i++) { nomCli[clientes[i].id] = clientes[i].nombre; }
  var filas = [];
  for (var k = 0; k < pedidos.length; k++) {
    var p = pedidos[k];
    if (!p || p.estado !== 'novedad') continue;
    if (!p.creado) continue;
    var d = dia(p.creado);
    if (!(d > limiteDia)) continue;
    var items = p.items || [];
    var partes = [];
    for (var j = 0; j < items.length; j++) {
      var it = items[j];
      var n = it.nombre || 'Producto';
      var c = Number(it.cantidad) || 1;
      partes.push(n + ' x' + c);
    }
    filas.push({
      numero: p.numero != null ? Number(p.numero) : null,
      fecha: fmt(p.creado),
      cliente: nomCli[p.clienteId] || p.clienteId || 'Sin dato',
      ciudad: p.ciudad || 'Sin dato',
      productos: partes.join('; ') || 'Sin dato',
      total: p.total != null ? Number(p.total) : null,
      estado: p.estado,
      _creado: p.creado
    });
  }
  filas.sort(function (a, b) { return Date.parse(b._creado) - Date.parse(a._creado); });
  var out = [];
  var tope = filas.length > 200 ? 200 : filas.length;
  for (var t = 0; t < tope; t++) {
    var f = filas[t];
    out.push({
      numero: f.numero,
      fecha: f.fecha,
      cliente: f.cliente,
      ciudad: f.ciudad,
      productos: f.productos,
      total: f.total,
      estado: f.estado
    });
  }
  return out;
}

