function consultar(datos) {
  var tablas = (datos && datos.tablas) || {};
  var pedidos = tablas.pedidos || [];
  var clientes = tablas.clientes || [];
  var nombres = {};
  var i;
  for (i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (c && c.id) nombres[c.id] = c.nombre || c.id;
  }
  var esVenta = function (e) {
    return e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad";
  };
  var agg = {};
  for (i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!p) continue;
    if (!esVenta(p.estado)) continue;
    var id = p.clienteId || "sin-cliente";
    if (!agg[id]) agg[id] = { total: 0, n: 0 };
    var t = typeof p.total === "number" ? p.total : 0;
    agg[id].total += t;
    agg[id].n += 1;
  }
  var lista = [];
  for (var k in agg) {
    if (Object.prototype.hasOwnProperty.call(agg, k)) {
      lista.push({ id: k, total: agg[k].total, n: agg[k].n });
    }
  }
  lista.sort(function (a, b) { return b.total - a.total; });
  var top = lista.slice(0, 10);
  var filas = [];
  for (i = 0; i < top.length; i++) {
    var v = top[i];
    filas.push({
      puesto: i + 1,
      cliente: nombres[v.id] || v.id,
      pedidos: v.n,
      total_comprado: v.total
    });
  }
  return filas;
}

