function diaBogota(iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); }
function calcular(datos) {
  var N = 365;
  var casos = (datos && datos.tablas && datos.tablas.casos) || [];
  var corte = diaBogota(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var suma = 0;
  var n = 0;
  for (var i = 0; i < casos.length; i++) {
    var c = casos[i];
    if (!c || !c.creado || !c.resuelto) continue;
    var d = diaBogota(c.creado);
    if (!(d > corte)) continue;
    var t0 = Date.parse(c.creado);
    var t1 = Date.parse(c.resuelto);
    if (isNaN(t0) || isNaN(t1) || t1 < t0) continue;
    suma += (t1 - t0) / 3600000;
    n++;
  }
  var prom = n === 0 ? 0 : suma / n;
  prom = Math.round(prom * 10) / 10;
  return { valor: prom, nota: "Promedio de horas entre creado y resuelto de " + n + " casos resueltos creados en los ultimos 365 dias." };
}

