function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var clientes = (datos && datos.tablas && datos.tablas.clientes) || [];
  var conteo = {};
  var total = 0;
  for (var i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (!c || !c.creado) continue;
    var mes = dia(c.creado).slice(0, 7);
    conteo[mes] = (conteo[mes] || 0) + 1;
    total += 1;
  }
  var claves = Object.keys(conteo).sort();
  var serie = [];
  if (claves.length > 0) {
    var minP = claves[0].split("-");
    var maxP = claves[claves.length - 1].split("-");
    var y = parseInt(minP[0], 10);
    var m = parseInt(minP[1], 10);
    var yFin = parseInt(maxP[0], 10);
    var mFin = parseInt(maxP[1], 10);
    while (y < yFin || (y === yFin && m <= mFin)) {
      var mm = (m < 10 ? "0" + m : "" + m);
      var etiqueta = y + "-" + mm;
      serie.push({ etiqueta: etiqueta, valor: conteo[etiqueta] || 0 });
      m += 1;
      if (m > 12) { m = 1; y += 1; }
    }
  }
  return {
    valor: total,
    unidad: "clientes",
    serie: serie,
    nota: "Cuenta clientes nuevos por mes segun fecha de creado en hora de Bogota usando todos los clientes."
  };
}

