function diasAtras(hoyMs, n) { return dia(new Date(hoyMs - n * 86400000).toISOString()); }
function dia(iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); }
function fmtBogota(iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " "); }
function consultar(datos) {
  var hoyMs = Date.parse(datos.hoy);
  var umbral365 = diasAtras(hoyMs, 365);
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var clientes = (datos.tablas && datos.tablas.clientes) || [];
  var porCliente = {};
  for (var i = 0; i < clientes.length; i++) { porCliente[clientes[i].id] = clientes[i]; }
  var filas = [];
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || p.estado !== "pendiente" || !p.creado) continue;
    var creadoMs = Date.parse(p.creado);
    if (isNaN(creadoMs)) continue;
    if (creadoMs > hoyMs) continue;
    var d = dia(p.creado);
    if (!(d > umbral365)) continue;
    var diffMs = hoyMs - creadoMs;
    if (!(diffMs > 3 * 86400000)) continue;
    var diasEspera = Math.floor(diffMs / 86400000);
    var c = porCliente[p.clienteId] || null;
    filas.push({
      numero: p.numero != null ? p.numero : null,
      fecha_creacion: fmtBogota(p.creado),
      dias_en_espera: diasEspera,
      cliente: c && c.nombre ? c.nombre : "Cliente sin nombre",
      telefono: c && c.telefonoEnmascarado ? c.telefonoEnmascarado : null,
      ciudad: p.ciudad != null ? p.ciudad : null,
      total: p.total != null ? p.total : null,
      estado: p.estado,
      _ord: creadoMs
    });
  }
  filas.sort(function (a, b) { return b._ord - a._ord; });
  var out = [];
  var n = filas.length > 200 ? 200 : filas.length;
  for (var k = 0; k < n; k++) {
    var f = filas[k];
    out.push({
      numero: f.numero,
      fecha_creacion: f.fecha_creacion,
      dias_en_espera: f.dias_en_espera,
      cliente: f.cliente,
      telefono: f.telefono,
      ciudad: f.ciudad,
      total: f.total,
      estado: f.estado
    });
  }
  return out;
}

